CREATE FUNCTION plate_variants AS plate -> arrayDistinct(arrayFold((variants, pos_chars) -> arrayFlatten(arrayMap(v -> arrayMap(c -> concat(v, c), pos_chars), variants)), arrayMap(pos -> if(pos <= length(upper(plate)), multiIf(substring(upper(plate), pos, 1) IN ('0', 'O', 'D', 'Q'), ['0', 'O', 'D', 'Q'], substring(upper(plate), pos, 1) IN ('1', 'I', 'L'), ['1', 'I', 'L'], substring(upper(plate), pos, 1) IN ('2', 'Z'), ['2', 'Z'], substring(upper(plate), pos, 1) IN ('3', '8', 'B'), ['3', '8', 'B'], substring(upper(plate), pos, 1) IN ('5', 'S'), ['5', 'S'], substring(upper(plate), pos, 1) IN ('6', 'G'), ['6', 'G'], [substring(upper(plate), pos, 1)]), CAST('[\'\']', 'Array(String)')), range(1, 11)), CAST('[\'\']', 'Array(String)')));
